function summaryFromSource(values: readonly string[]): StockMaterialSummaryValues {
  const summary = blankStockMaterialSummary();
  STOCK_MATERIAL_FF_SUMMARY_FIELDS.forEach((field, index) => {
    summary[field] = values[index] ?? "";
  });
  return summary;
}

function dailyFromSource(values: readonly string[]): StockMaterialDailyValues {
  const daily = blankStockMaterialDaily();
  STOCK_MATERIAL_FF_DAILY_FIELDS.forEach((field, index) => {
    daily[field] = values[index] ?? "";
  });
  return daily;
}

function isoDate(period: StockMaterialPeriod, day: number): string {
  const year = period.year_be - 543;
  return `${year}-${String(period.month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
}

/** Return new, unshared rows and day values for each React State initialization. */
export function createStockMaterialMockSheets(): StockMaterialSheet[] {
  return SOURCE_SHEETS.map(({ period, rows }) => ({
    id: stockMaterialPeriodKey(period),
    period: { ...period },
    source_sheet_name: stockMaterialSourceSheetName(period),
    created_at: "",
    updated_at: "",
    rows: rows.map(([
      source_row, no, category, code, name, unit,
      summary, remark, safety_stock, sourceDaily,
    ]) => ({
      item: { source_row, no, category, code, name, unit },
      summary: summaryFromSource(summary),
      remark,
      safety_stock,
      daily: sourceDaily.map(([day, values]) => ({
        date: isoDate(period, day),
        values: dailyFromSource(values),
      })),
    })),
  }));
}

/** A separate copy of subtotal/GT/ST values, not part of item rows. */
export function createStockMaterialMockSourceTotals(): StockMaterialSourceTotalRow[] {
  return SOURCE_TOTALS.map(([source_sheet_name, source_row, label, summary]) => ({
    source_sheet_name,
    source_row,
    label,
    summary: summaryFromSource(summary),
  }));
}
